#include <math.h>
#include <stdio.h>
#include <stdlib.h>

void stampa_intestazione(void) {
    printf("=== SCHEDA LOTTO ===\n");
}

double calcola_area(double larghezza, double lunghezza) {
    return larghezza * lunghezza;
}

double calcola_perimetro(double larghezza, double lunghezza) {
    return 2.0 * (larghezza + lunghezza);
}

bool e_quadrato(double larghezza, double lunghezza) {
    return fabs(larghezza - lunghezza) <= 1e-9;
}

int main(void) {
    char riga[128];
    double larghezza = 0.0;
    double lunghezza = 0.0;
    double prezzo_mq = 0.0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%lf %lf %lf %c", &larghezza, &lunghezza, &prezzo_mq, &extra) != 3 ||
        larghezza <= 0.0 || lunghezza <= 0.0 || prezzo_mq < 0.0) {
        fprintf(stderr, "Errore: dati del lotto non validi.\n");
        return EXIT_FAILURE;
    }

    double area = calcola_area(larghezza, lunghezza);
    double perimetro = calcola_perimetro(larghezza, lunghezza);
    double valore = area * prezzo_mq;

    stampa_intestazione();
    printf("Area: %.2f mq\n", area);
    printf("Perimetro: %.2f m\n", perimetro);
    if (e_quadrato(larghezza, lunghezza)) {
        printf("Forma: Quadrato\n");
    } else {
        printf("Forma: Rettangolo\n");
    }
    printf("Valore stimato: %.2f euro\n", valore);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

long distanza_manhattan(long x1, long y1, long x2, long y2);
int sbilanciamento_assi(long x1, long y1, long x2, long y2);
long long differenza_energia(long long e1, long long e2);
int applica_margine(int soglia);

int main(void) {
    char riga[128];
    long x1 = 0, y1 = 0, x2 = 0, y2 = 0;
    int soglia = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%ld %ld %ld %ld %d %c", &x1, &y1, &x2, &y2, &soglia, &extra) != 5 ||
        labs(x1) > 1'000'000L || labs(y1) > 1'000'000L ||
        labs(x2) > 1'000'000L || labs(y2) > 1'000'000L ||
        soglia < 0 || soglia > 10'000'000) {
        fprintf(stderr, "Errore: parametri del percorso non validi.\n");
        return EXIT_FAILURE;
    }

    long distanza = distanza_manhattan(x1, y1, x2, y2);
    int sbilanciamento = sbilanciamento_assi(x1, y1, x2, y2);
    long long e1 = (long long)x1 * x1 + (long long)y1 * y1;
    long long e2 = (long long)x2 * x2 + (long long)y2 * y2;
    long long diff_en = differenza_energia(e1, e2);
    int soglia_estesa = applica_margine(soglia);

    printf("Distanza Manhattan: %ld\n", distanza);
    printf("Sbilanciamento assi: %d\n", sbilanciamento);
    printf("Differenza energia: %lld\n", diff_en);
    printf("Soglia originale in main: %d\n", soglia);
    printf("Soglia estesa restituita: %d\n", soglia_estesa);
    if (distanza <= soglia_estesa) {
        printf("Esito: Entro soglia estesa\n");
    } else {
        printf("Esito: Oltre soglia estesa\n");
    }
    return EXIT_SUCCESS;
}

long distanza_manhattan(long x1, long y1, long x2, long y2) {
    return labs(x2 - x1) + labs(y2 - y1);
}

int sbilanciamento_assi(long x1, long y1, long x2, long y2) {
    long dx = labs(x2 - x1);
    long dy = labs(y2 - y1);
    return abs((int)(dx - dy));
}

long long differenza_energia(long long e1, long long e2) {
    return llabs(e1 - e2);
}

int applica_margine(int soglia) {
    soglia += 10;
    return soglia;
}

#include <stdio.h>
#include <stdlib.h>

long aggiorna_totale_wh(int consumo);
int aggiorna_picco_wh(int consumo);
int conta_oltre_soglia(int consumo, int soglia);

int main(void) {
    constexpr int SOGLIA_WH = 500;
    char riga[128];
    int consumo = 0;
    char extra = '\0';
    int cicli = 0;
    long totale = 0;
    int picco = 0;
    int oltre_soglia = 0;

    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%d %c", &consumo, &extra) != 1 ||
            consumo < 0 || consumo > 100'000) {
            fprintf(stderr, "Errore: consumo non valido.\n");
            return EXIT_FAILURE;
        }
        ++cicli;
        totale = aggiorna_totale_wh(consumo);
        picco = aggiorna_picco_wh(consumo);
        oltre_soglia = conta_oltre_soglia(consumo, SOGLIA_WH);
        printf("Ciclo %d: consumo=%d Wh, cumulato=%ld Wh, picco=%d Wh\n",
               cicli, consumo, totale, picco);
    }

    if (cicli == 0) {
        printf("Nessun ciclo registrato.\n");
        return EXIT_SUCCESS;
    }
    printf("Cicli totali: %d\n", cicli);
    printf("Consumo totale: %ld Wh\n", totale);
    printf("Picco massimo: %d Wh\n", picco);
    printf("Cicli sopra %d Wh: %d\n", SOGLIA_WH, oltre_soglia);
    return EXIT_SUCCESS;
}

long aggiorna_totale_wh(int consumo) {
    static long totale = 0;
    totale += consumo;
    return totale;
}

int aggiorna_picco_wh(int consumo) {
    static int picco = -1;
    if (consumo > picco) {
        picco = consumo;
    }
    return picco;
}

int conta_oltre_soglia(int consumo, int soglia) {
    static int conteggio = 0;
    if (consumo > soglia) {
        ++conteggio;
    }
    return conteggio;
}

#include <stdio.h>
#include <stdlib.h>

long long potenza_veloce(int base, int esponente);
int somma_cifre_ric(long long n);
void stampa_binario_ric(long long n);

int main(void) {
    char riga[128];
    int base = 0;
    int esponente = 0;
    long long numero = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %lld %c", &base, &esponente, &numero, &extra) != 3 ||
        base < -10 || base > 10 || esponente < 0 || esponente > 15 ||
        numero < 0 || numero > 1'000'000'000LL) {
        fprintf(stderr, "Errore: parametri non validi.\n");
        return EXIT_FAILURE;
    }

    printf("Potenza %d^%d: %lld\n", base, esponente, potenza_veloce(base, esponente));
    printf("Somma cifre di %lld: %d\n", numero, somma_cifre_ric(numero));
    printf("Binario di %lld: ", numero);
    stampa_binario_ric(numero);
    putchar('\n');
    return EXIT_SUCCESS;
}

long long potenza_veloce(int base, int esponente) {
    if (esponente == 0) {
        return 1;
    }
    long long meta = potenza_veloce(base, esponente / 2);
    if (esponente % 2 == 0) {
        return meta * meta;
    }
    return meta * meta * base;
}

int somma_cifre_ric(long long n) {
    if (n < 10) {
        return (int)n;
    }
    return (int)(n % 10) + somma_cifre_ric(n / 10);
}

void stampa_binario_ric(long long n) {
    if (n >= 2) {
        stampa_binario_ric(n / 2);
    }
    putchar('0' + (int)(n % 2));
}

#include <stdio.h>
#include <stdlib.h>

bool e_bisestile(int anno);
int giorni_del_mese(int mese, int anno);
bool data_valida(int g, int m, int a);
int giorno_dell_anno(int g, int m, int a);
long giorni_dal_1900(int g, int m, int a);

int main(void) {
    char riga[128];
    int g1 = 0, m1 = 0, a1 = 0, g2 = 0, m2 = 0, a2 = 0;
    char extra = '\0';
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %d %c", &g1, &m1, &a1, &extra) != 3 ||
        !data_valida(g1, m1, a1)) {
        fprintf(stderr, "Errore: prima data non valida.\n");
        return EXIT_FAILURE;
    }
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %d %c", &g2, &m2, &a2, &extra) != 3 ||
        !data_valida(g2, m2, a2)) {
        fprintf(stderr, "Errore: seconda data non valida.\n");
        return EXIT_FAILURE;
    }
    long d1 = giorni_dal_1900(g1, m1, a1);
    long d2 = giorni_dal_1900(g2, m2, a2);
    printf("Data 1: %d/%d/%d (giorno %d, bisestile=%d)\n",
           g1, m1, a1, giorno_dell_anno(g1, m1, a1), e_bisestile(a1));
    printf("Data 2: %d/%d/%d (giorno %d, bisestile=%d)\n",
           g2, m2, a2, giorno_dell_anno(g2, m2, a2), e_bisestile(a2));
    printf("Distanza: %ld giorni\n", labs(d2 - d1));
    return EXIT_SUCCESS;
}

bool e_bisestile(int anno) {
    return (anno % 400 == 0) || (anno % 4 == 0 && anno % 100 != 0);
}

int giorni_del_mese(int mese, int anno) {
    switch (mese) {
        case 4: case 6: case 9: case 11: return 30;
        case 2: return e_bisestile(anno) ? 29 : 28;
        default: return (mese >= 1 && mese <= 12) ? 31 : 0;
    }
}

bool data_valida(int g, int m, int a) {
    return a >= 1900 && a <= 2100 && m >= 1 && m <= 12 &&
           g >= 1 && g <= giorni_del_mese(m, a);
}

int giorno_dell_anno(int g, int m, int a) {
    int tot = g;
    for (int i = 1; i < m; ++i) {
        tot += giorni_del_mese(i, a);
    }
    return tot;
}

long giorni_dal_1900(int g, int m, int a) {
    long tot = giorno_dell_anno(g, m, a);
    for (int y = 1900; y < a; ++y) {
        tot += e_bisestile(y) ? 366L : 365L;
    }
    return tot;
}
